={{ (() => {
    const d = $json.briefing_data || {};
    const k = d.kpis || {};
    const verts = d.verticals || [];
    const monthly = d.monthly_revenue || [];
    const annual = d.annual_target || 0;

    // Prorate the current in-progress month so projection isn't biased low
    const now = new Date();
    const dayOfMonth = now.getDate();
    const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
    const currentMonthPrefix = now.toISOString().slice(0, 7);

    const revenues = monthly.map(m => {
      const rev = m.revenue || 0;
      if (m.month && m.month.startsWith(currentMonthPrefix)) {
        return rev * (daysInMonth / dayOfMonth);
      }
      return rev;
    }).filter(Boolean);

    const monthsLeft = 12 - revenues.length;
    let base = 0, pessimistic = 0, optimistic = 0;
    if (revenues.length >= 2) {
      const weights = revenues.map((_, i) => i + 1);
      const wSum = revenues.reduce((s, v, i) => s + v * weights[i], 0);
      const wTotal = weights.reduce((a, b) => a + b, 0);
      const avgWeighted = wSum / wTotal;
      const recent3 = revenues.slice(-3);
      base = (k.revenue_ytd || 0) + avgWeighted * monthsLeft;
      pessimistic = (k.revenue_ytd || 0) + Math.min(...recent3) * monthsLeft;
      optimistic = (k.revenue_ytd || 0) + Math.max(...recent3) * monthsLeft;
    }

    const vertLines = verts.map(v =>
      '- ' + v.vertical_name + ': $' + Math.round(v.revenue_qtd || 0).toLocaleString() + ' / $' +
      Math.round(v.goal_qtd || 0).toLocaleString() + ' (' + (v.goal_qtd > 0 ? (v.revenue_qtd / v.goal_qtd * 100).toFixed(0) : '0') + '%)'
    ).join('\n');

    return JSON.stringify({
      model: 'anthropic/claude-sonnet-4-6',
      max_tokens: 1024,
      messages: [{
        role: 'user',
        content: `You are the chief of staff for MX3 Diagnostics, a medical device company that sells hydration testing systems (HTS Pro) and consumable hydration test strips. Revenue comes from device sales,
  test strip reorders, and sweat test kits. Do NOT use razor/blade terminology. Write today's executive briefing from this data.

  DATA:
  - YTD Revenue: $${Math.round(k.revenue_ytd || 0).toLocaleString()} (Annual target: $${Math.round(annual).toLocaleString()})
  - YTD Progress: ${annual > 0 ? ((k.revenue_ytd || 0) / annual * 100).toFixed(1) : '0'}%
  - Revenue MoM growth: ${k.revenue_mom_pct || 0}%
  - Sales velocity: ${k.sales_velocity_days || 0} days
  - Daily inbound leads: ${k.daily_inbound_leads || 0} (7-day avg: ${k.leads_7day_avg || 0})
  - Lead volume MoM: ${k.lead_volume_mom_pct || 0}%
  - New customer revenue MTD: $${Math.round(k.new_customer_revenue || 0).toLocaleString()} (${k.new_customer_deals || 0} deals)
  - Existing customer revenue MTD: $${Math.round(k.existing_customer_revenue || 0).toLocaleString()} (${k.existing_customer_deals || 0} deals)
  - Strips per device: ${k.strips_per_device || 0}
  - Devices sold YTD: ${k.total_devices_sold_ytd || 0}
  - Strip packs sold YTD: ${k.total_strips_sold_ytd || 0}

  VERTICALS (QTD revenue / goal):
  ${vertLines}

  PROJECTION (weighted monthly run rate; current month prorated to full-month equivalent):
  - Pessimistic EOY: $${Math.round(pessimistic).toLocaleString()}
  - Base EOY: $${Math.round(base).toLocaleString()}
  - Optimistic EOY: $${Math.round(optimistic).toLocaleString()}

  Return JSON with this exact structure:
  {
    "summary": "2-3 sentence overview of business state",
    "projection": "1-2 sentences on EOY trajectory with confidence range",
    "actions": [
      {"signal": "what the data shows", "action": "specific next step to take", "urgency": "high|medium|low"}
    ]
  }

  Rules:
  - Write as a chief of staff briefing the CEO at 6 AM
  - Be direct and specific. No filler.
  - Actions must be concrete ("Schedule X with Y this week") not vague ("Consider improving Z")
  - 3-5 actions max, ordered by urgency
  - Use the actual numbers provided. Do not fabricate any figures.
  - Return ONLY valid JSON, no markdown wrapping

  DATA QUALITY NOTES (factor these in):
  - Revenue, deals, verticals, and regions come from QuickBooks invoices (authoritative). HubSpot is NOT used for financials.
  - "Unassigned" vertical = QBO customers not yet mapped in customer_rep_map. Today that is $${Math.round((verts.find(v => v.vertical_name === 'Unassigned') || {}).revenue_qtd || 0).toLocaleString()} QTD. Treat
   as a classification gap (action: reclassify customers), NOT a revenue problem.
  - Vertical goal progress shows 0% when goals are unset in the goals table. Skip goal commentary until goals are set for the current quarter.
  - Strips per device is a YTD ratio (strips sold / devices sold this year). Does not reflect lifetime reorder behavior from prior-year device owners.
  - Lead volume MoM requires 30+ days of snapshot history. 0% early in deployment means insufficient data, not flat leads.
  - Daily inbound leads currently 0 — the HubSpot lead metric is not yet wired to produce real counts.
  - Do NOT flag data quality issues as business emergencies. If a metric is likely zero due to missing CRM data or unset goals, note it as a "data gap to fix" not a "revenue crisis."`
      }]
    });
  })() }}

