const resp = $input.first().json;
  const raw = resp.body?.choices?.[0]?.message?.content || '';

  if (!raw) {
    throw new Error('OpenRouter returned empty content');
  }

  const cleaned = raw.replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '').trim();

  let parsed = { summary: '', projection: '', actions: [] };
  try {
    parsed = JSON.parse(cleaned);
  } catch (e) {
    parsed.summary = cleaned;
  }

  // Simple djb2 hash — good enough for duplicate detection
  let h = 5381;
  for (let i = 0; i < cleaned.length; i++) {
    h = ((h << 5) + h + cleaned.charCodeAt(i)) | 0;
  }
  const inputHash = (h >>> 0).toString(16).padStart(8, '0');

  return [{
    json: {
      briefing_date: new Date().toISOString().split('T')[0],
      summary: parsed.summary || '',
      projection: parsed.projection || '',
      actions: JSON.stringify(parsed.actions || []),
      model_used: resp.body?.model || 'anthropic/claude-sonnet-4-6',
      input_hash: inputHash,
      openrouter_id: resp.body?.id || '',
    }
  }];

// Process QBO invoices and prepare for Postgres upsert
const input = $input.first().json;
const invoices = input.QueryResponse?.Invoice || [];

if (invoices.length === 0) {
    return [{ json: { upsert_sql: 'SELECT 1 AS no_op;', upserted: 0 } }];
  }

const STATE_TO_REGION = {
    'Northeast': ['CT','MA','ME','NH','NJ','NY','PA','RI','VT'],
    'South':['AL','AR','DC','DE','FL','GA','KY','LA','MD','MS','NC','OK','SC','TN','TX','VA','WV'],
    'Midwest':   ['IA','IL','IN','KS','MI','MN','MO','ND','NE','OH','SD','WI'],
    'West':      ['AK','AZ','CA','CO','HI','ID','MT','NM','NV','OR','UT','WA','WY']
  };

function stateToRegion(state) {
  if (!state) return 'Unknown';
  for (const [region, states] of Object.entries(STATE_TO_REGION)) {
    if (states.includes(state)) return region;
  }
  return 'Unknown';
}

function extractState(shipAddr) {
  if (!shipAddr) return null;
  for (const key of ['Line5','Line4','Line3','Line2','Line1']) {
    const line = shipAddr[key] || '';
    const m = line.match(/\b([A-Z]{2})\s+\d{5}/);
    if (m) return m[1];
  }
  return null;
}

const upsertValues = invoices.map(inv => {
  const lines = (inv.Line || []).filter(l =>
    l.DetailType === 'SalesItemLineDetail' &&
    l.SalesItemLineDetail?.ItemRef?.value !== '55'
  );

  let device_rev = 0, strip_rev = 0, sweat_rev = 0, acc_rev = 0;
  let device_qty = 0, strip_qty = 0, sweat_qty = 0, acc_qty = 0;

  for (const line of lines) {
    const amt = parseFloat(line.Amount || 0);
    const qty = parseInt(line.SalesItemLineDetail?.Qty || 0);
    const acct = line.SalesItemLineDetail?.ItemAccountRef?.name || '';

    if (acct.includes('41000')) { device_rev += amt; device_qty += qty; }
    else if (acct.includes('44000')) { strip_rev += amt; strip_qty += qty; }
    else if (acct.includes('43000')) { sweat_rev += amt; sweat_qty += qty; }
    else if (acct.includes('45000')) { acc_rev += amt; acc_qty += qty; }
  }

  const product_revenue = device_rev + strip_rev + sweat_rev + acc_rev;
  const ship_state = extractState(inv.ShipAddr);
  const ship_region = stateToRegion(ship_state);

  return {
    qbo_invoice_id: inv.Id,
    doc_number: inv.DocNumber || '',
    txn_date: inv.TxnDate,
    customer_id: inv.CustomerRef?.value || '',
    customer_name: (inv.CustomerRef?.name || '').replace(/'/g, "''"),
    total_amt: inv.TotalAmt || 0,
    product_revenue,
    device_revenue: device_rev,
    strip_revenue: strip_rev,
    sweat_revenue: sweat_rev,
    accessory_revenue: acc_rev,
    device_qty, strip_qty, sweat_qty, accessory_qty: acc_qty,
    ship_state, ship_region,
    balance: inv.Balance || 0,
    invoice_status: inv.EInvoiceStatus || 'Unknown',
    raw_json: JSON.stringify(inv).replace(/'/g, "''"),
    last_updated_qbo: inv.MetaData?.LastUpdatedTime || ''
  };
});

// Build single SQL with multiple UPSERT statements
const sql = upsertValues.map(v => `
  INSERT INTO qbo_invoices (qbo_invoice_id, doc_number, txn_date, customer_id, customer_name,
    total_amt, product_revenue, device_revenue, strip_revenue, sweat_revenue, accessory_revenue,
    device_qty, strip_qty, sweat_qty, accessory_qty, ship_state, ship_region, balance, invoice_status,
    raw_json, last_updated_qbo, synced_at)
  VALUES ('${v.qbo_invoice_id}', '${v.doc_number}', '${v.txn_date}', '${v.customer_id}', '${v.customer_name}',
    ${v.total_amt}, ${v.product_revenue}, ${v.device_revenue}, ${v.strip_revenue},
    ${v.sweat_revenue}, ${v.accessory_revenue},
    ${v.device_qty}, ${v.strip_qty}, ${v.sweat_qty}, ${v.accessory_qty},
    ${v.ship_state ? `'${v.ship_state}'` : 'NULL'}, '${v.ship_region}',
    ${v.balance}, '${v.invoice_status}',
    '${v.raw_json}'::jsonb, '${v.last_updated_qbo}', NOW())
  ON CONFLICT (qbo_invoice_id) DO UPDATE SET
    total_amt = EXCLUDED.total_amt, product_revenue = EXCLUDED.product_revenue,
    device_revenue = EXCLUDED.device_revenue, strip_revenue = EXCLUDED.strip_revenue,
    sweat_revenue = EXCLUDED.sweat_revenue, accessory_revenue = EXCLUDED.accessory_revenue,
    device_qty = EXCLUDED.device_qty, strip_qty = EXCLUDED.strip_qty,
    sweat_qty = EXCLUDED.sweat_qty, accessory_qty = EXCLUDED.accessory_qty,
    balance = EXCLUDED.balance, invoice_status = EXCLUDED.invoice_status,
    raw_json = EXCLUDED.raw_json, last_updated_qbo = EXCLUDED.last_updated_qbo,
    synced_at = NOW();
`).join('\n');

return [{ json: { upsert_sql: sql, upserted: upsertValues.length } }];

const results = $input.first().json.results || [];

  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  const yesterdayStr = yesterday.toISOString().split('T')[0];

  const sevenDaysAgo = new Date();
  sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

  const daily_inbound_leads = results.filter(l => {
    const d = l.properties?.hs_createdate;
    return d && d.startsWith(yesterdayStr);
  }).length;

  const leads_7day = results.filter(l => {
    const d = l.properties?.hs_createdate;
    if (!d) return false;
    return new Date(d) >= sevenDaysAgo;
  }).length;

  return [{
    json: {
      daily_inbound_leads,
      leads_7day_avg: Math.round((leads_7day / 7) * 10) / 10
    }
  }];
